    tree: dict[str, Any], aggregates: frozenset[str]
) -> list[tuple[str, tuple[str, ...]]]:
    """Every aggregate in this parse tree, with the columns it is applied to.

    A windowed aggregate counts: `sum(x) OVER ()` multiplies exactly as a grouped sum does.
    An aggregate with no columns at all -- `count(*)` -- comes back with none, which is a
    different refusal rather than an absent one.
    """
    found: list[tuple[str, tuple[str, ...]]] = []

    def walk(node: object) -> None:
        if isinstance(node, list):
            for value in node:
                walk(value)
            return
        if not isinstance(node, dict):
            return
        name = str(node.get("function_name", "")).lower()
        aggregate = node.get("class") in ("FUNCTION", "WINDOW") and not node.get("is_operator")
        if aggregate and name in aggregates:
            found.append((name, tuple(_columns_under(node.get("children", [])))))
        for value in node.values():
            walk(value)

    walk(tree.get("statements"))
    return found


